"""PDF103 printed 197–198: 6.2.3 unbiasedness, definition of unbiased estimator, Examples 6.2–6.3 (proofs), Example 6.4 statement."""
from class12_statistics_common import Builder, save

PROOF = ('Proof:', 'ثبوت:', 'ثبوت:')
T = r'\hat{\theta}'
b = Builder()
b.p('efficient and sufficient. Only two properties, unbiasedness and efficiency are discussed here in detail.', 'مؤثر اور کافی ہو۔ یہاں صرف دو خصوصیات، غیر جانبداری اور کارکردگی، پر تفصیل سے بحث کی گئی ہے۔', 'موثر او کافي وي. دلته یوازې دوه ځانګړنې، بې‌پلوي او موثریت، په تفصیل سره څېړل شوې.')
b.h('6.2.3 Unbiasedness', '6.2.3 غیر جانبداری', '6.2.3 بې‌پلوي')
b.p('It is not possible for an estimator to obtain correct estimate from each and every sample, even though if samples are drawn randomly. However, if this estimator on the average (i.e. considering all possible samples), give an estimate equal to the population parameter then this property of the estimator is called unbiasedness.', 'کسی تخمین کار کے لیے ہر ایک نمونے سے درست تخمینہ حاصل کرنا ممکن نہیں، چاہے نمونے تصادفی طور پر نکالے جائیں۔ تاہم اگر یہ تخمین کار اوسطاً (یعنی تمام ممکنہ نمونوں کو مدِنظر رکھتے ہوئے) آبادی کے پیرامیٹر کے برابر تخمینہ دے تو تخمین کار کی اس خاصیت کو غیر جانبداری کہتے ہیں۔', 'د یوه اټکلوونکي لپاره ممکنه نه ده چې له هرې نمونې څخه سم اټکل ترلاسه کړي، که څه هم نمونې په تصادفي ډول راایستل شي. خو که دا اټکلوونکی په اوسط ډول (یعنې د ټولو شونو نمونو په پام کې نیولو سره) د نفوس له پارامټر سره برابر اټکل ورکړي، نو د اټکلوونکي دې ځانګړنې ته بې‌پلوي وایي.')
b.h('Definition of unbiased estimator:', 'غیر جانبدار تخمین کار کی تعریف:', 'د بې‌پلوه اټکلوونکي تعریف:')
b.p(f'An estimator is said to be unbiased if the mean of its sampling distribution is equal to the true value of the parameter, otherwise, the estimator is said to be biased. For example, if ${T}$ is a point estimator of the parameter θ and $E({T})=\\theta$, then ${T}$ is called an unbiased estimator of θ. If $E({T})\\neq\\theta$ means that ${T}$ is a biased estimator of θ. Further, if $E({T})>\\theta$ means ${T}$ is positively biased. If $E({T})<\\theta$ means that ${T}$ is negatively biased. Remember that in previous unit we have shown in practical examples that $E(\\overline{{X}})=\\mu_{{\\overline{{x}}}}=\\mu$. This implies that $\\overline{{X}}=\\frac{{\\Sigma x}}{{n}}$ is an unbiased estimator for μ. Similarly, $E(\\hat{{p}})=p$ means that $\\hat{{p}}=\\frac{{X}}{{n}}$ is an unbiased estimator of p. The bias of an estimator ${T}$ is given by $B({T})=[E({T})-\\theta]$.',
    f'ایک تخمین کار غیر جانبدار کہلاتا ہے اگر اس کی نمونہ جاتی تقسیم کا اوسط پیرامیٹر کی حقیقی قیمت کے برابر ہو، ورنہ تخمین کار جانبدار کہلاتا ہے۔ مثلاً اگر ${T}$ پیرامیٹر θ کا نقطہ تخمین کار ہو اور $E({T})=\\theta$ ہو تو ${T}$ کو θ کا غیر جانبدار تخمین کار کہتے ہیں۔ اگر $E({T})\\neq\\theta$ ہو تو اس کا مطلب ہے کہ ${T}$، θ کا جانبدار تخمین کار ہے۔ مزید یہ کہ اگر $E({T})>\\theta$ ہو تو ${T}$ مثبت طور پر جانبدار ہے۔ اگر $E({T})<\\theta$ ہو تو ${T}$ منفی طور پر جانبدار ہے۔ یاد رکھیں کہ پچھلے یونٹ میں ہم نے عملی مثالوں میں دکھایا کہ $E(\\overline{{X}})=\\mu_{{\\overline{{x}}}}=\\mu$۔ اس کا مطلب ہے کہ $\\overline{{X}}=\\frac{{\\Sigma x}}{{n}}$، μ کا غیر جانبدار تخمین کار ہے۔ اسی طرح $E(\\hat{{p}})=p$ کا مطلب ہے کہ $\\hat{{p}}=\\frac{{X}}{{n}}$، p کا غیر جانبدار تخمین کار ہے۔ تخمین کار ${T}$ کی جانبداری $B({T})=[E({T})-\\theta]$ ہے۔',
    f'یو اټکلوونکی بې‌پلوه بلل کېږي که د هغه د نمونوي وېش منځنی د پارامټر له رښتیني قیمت سره برابر وي، که نه اټکلوونکی پلوي بلل کېږي. د بېلګې په توګه که ${T}$ د θ پارامټر ټکي‌ییز اټکلوونکی وي او $E({T})=\\theta$ وي، نو ${T}$ د θ بې‌پلوه اټکلوونکی بلل کېږي. که $E({T})\\neq\\theta$ وي مانا یې دا ده چې ${T}$ د θ پلوي اټکلوونکی دی. سربېره پر دې که $E({T})>\\theta$ وي مانا یې دا ده چې ${T}$ مثبت پلوي دی. که $E({T})<\\theta$ وي مانا یې دا ده چې ${T}$ منفي پلوي دی. په یاد ولرئ چې په تېر واحد کې مو په عملي بېلګو کې وښودل چې $E(\\overline{{X}})=\\mu_{{\\overline{{x}}}}=\\mu$. دا ښيي چې $\\overline{{X}}=\\frac{{\\Sigma x}}{{n}}$ د μ بې‌پلوه اټکلوونکی دی. همداراز $E(\\hat{{p}})=p$ مانا دا ده چې $\\hat{{p}}=\\frac{{X}}{{n}}$ د p بې‌پلوه اټکلوونکی دی. د اټکلوونکي ${T}$ پلوي $B({T})=[E({T})-\\theta]$ ده.')
b.h('Example 6.2', 'مثال 6.2', 'بېلګه 6.2')
b.p('Show that sample mean $\\overline{X}$ is an unbiased estimator of the population mean μ.', 'ثابت کریں کہ نمونے کا اوسط $\\overline{X}$ آبادی کے اوسط μ کا غیر جانبدار تخمین کار ہے۔', 'وښایاست چې د نمونې منځنی $\\overline{X}$ د نفوس د منځني μ بې‌پلوه اټکلوونکی دی.')
b.h(*PROOF)
b.p('Consider a random sample $X_1,\\ldots,X_n$ from a normal population having mean μ and variance $\\sigma^2$, then by definition,', 'μ اوسط اور $\\sigma^2$ تغیر والی نارمل آبادی سے ایک تصادفی نمونہ $X_1,\\ldots,X_n$ لیں، تو تعریف کے مطابق،', 'د μ منځني او $\\sigma^2$ واریانس لرونکي نورمال نفوس څخه یوه تصادفي نمونه $X_1,\\ldots,X_n$ په پام کې ونیسئ، نو د تعریف له مخې،')
b.eq(r'\overline{X}=\frac{1}{n}\sum_{i=1}^{n}X_i')
b.p('Taking expectation on both sides to have', 'دونوں طرف توقع لینے سے', 'دواړو خواوو ته تمه اخیستلو سره')
b.mlines([r'E(\overline{X})=\frac{1}{n}E\left[\sum_{i=1}^{n}X_i\right]', r'=\frac{1}{n}[E(X_1)+E(X_2)+\cdots+E(X_n)]'])
b.p('$=\\frac{1}{n}(\\mu+\\mu+\\cdots+\\mu)$ (As $X_i$’s are drawn from a population having mean μ)', '$=\\frac{1}{n}(\\mu+\\mu+\\cdots+\\mu)$ (کیونکہ $X_i$ ایسی آبادی سے نکالے گئے ہیں جس کا اوسط μ ہے)', '$=\\frac{1}{n}(\\mu+\\mu+\\cdots+\\mu)$ (ځکه چې $X_i$ له داسې نفوس څخه راایستل شوي چې منځنی یې μ دی)')
b.p('$=\\frac{n\\mu}{n}=\\mu$ This implies that $\\overline{X}$ is an unbiased estimator of μ.', '$=\\frac{n\\mu}{n}=\\mu$ اس کا مطلب ہے کہ $\\overline{X}$، μ کا غیر جانبدار تخمین کار ہے۔', '$=\\frac{n\\mu}{n}=\\mu$ دا ښيي چې $\\overline{X}$ د μ بې‌پلوه اټکلوونکی دی.')
b.h('Example 6.3', 'مثال 6.3', 'بېلګه 6.3')
b.p('Show that sample proportion $\\hat{p}$ is an unbiased estimator of population proportion p.', 'ثابت کریں کہ نمونے کا تناسب $\\hat{p}$ آبادی کے تناسب p کا غیر جانبدار تخمین کار ہے۔', 'وښایاست چې د نمونې تناسب $\\hat{p}$ د نفوس د تناسب p بې‌پلوه اټکلوونکی دی.')
b.h(*PROOF)
b.p('By definition $\\hat{p}=\\frac{X}{n}$', 'تعریف کے مطابق $\\hat{p}=\\frac{X}{n}$', 'د تعریف له مخې $\\hat{p}=\\frac{X}{n}$')
b.eq(r'E(\hat{p})=E\left(\frac{X}{n}\right)=\frac{1}{n}E(X)')
b.p('$=\\frac{1}{n}(np)$ (As X is Binomial random variable having mean np)', '$=\\frac{1}{n}(np)$ (کیونکہ X دو رقمی تصادفی متغیر ہے جس کا اوسط np ہے)', '$=\\frac{1}{n}(np)$ (ځکه چې X بینومیل تصادفي متغیر دی چې منځنی یې np دی)')
b.p('$=p$. It means that $\\hat{p}$ is an unbiased estimator of p.', '$=p$۔ اس کا مطلب ہے کہ $\\hat{p}$، p کا غیر جانبدار تخمین کار ہے۔', '$=p$. مانا یې دا ده چې $\\hat{p}$ د p بې‌پلوه اټکلوونکی دی.')
b.h('Example 6.4', 'مثال 6.4', 'بېلګه 6.4')
b.p('Show that sample variance $s^2=\\frac{1}{n-1}\\sum_{i=1}^{n}(X_i-\\overline{X})^2$ is an unbiased estimator of population variance $\\sigma^2$.', 'ثابت کریں کہ نمونے کا تغیر $s^2=\\frac{1}{n-1}\\sum_{i=1}^{n}(X_i-\\overline{X})^2$ آبادی کے تغیر $\\sigma^2$ کا غیر جانبدار تخمین کار ہے۔', 'وښایاست چې د نمونې واریانس $s^2=\\frac{1}{n-1}\\sum_{i=1}^{n}(X_i-\\overline{X})^2$ د نفوس د واریانس $\\sigma^2$ بې‌پلوه اټکلوونکی دی.')
rec = b.build('stat12-p103-unbiasedness', '6.2.3 Unbiasedness — Examples 6.2–6.4', '6.2.3 غیر جانبداری — مثالیں 6.2–6.4', '6.2.3 بې‌پلوي — بېلګې 6.2–6.4', 103, [197, 198])

